package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONObject;import java.util.UUID;
/** Atomic exchange: removes one currency/account and adds another currency/account as one indivisible operation. */
public final class CurrencyExchangeStore {
 private final CoreStore.DbProvider provider;private final String deviceId;public CurrencyExchangeStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public String exchange(String businessDay,String fromAccount,double fromAmount,String fromCurrency,String toAccount,double toAmount,String toCurrency,String notes)throws Exception{String day=req(businessDay,"يوم العمل"),fa=req(fromAccount,"الخزنة المصدر"),ta=req(toAccount,"الخزنة الهدف"),fc=MoneyRules.currency(fromCurrency),tc=MoneyRules.currency(toCurrency);MoneyRules.requireSupported(fa,fc);MoneyRules.requireSupported(ta,tc);if(!Double.isFinite(fromAmount)||fromAmount<=0||!Double.isFinite(toAmount)||toAmount<=0)throw new IllegalArgumentException("مبالغ الصرف يجب أن تكون أكبر من صفر");if(fc.equals(tc))throw new IllegalArgumentException("استخدم تحويل الخزنة العادي عندما تكون العملة نفسها");long now=System.currentTimeMillis();String id="exchange-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("exchange_id",id);v.put("from_account",fa);v.put("from_amount",fromAmount);v.put("from_currency",fc);v.put("to_account",ta);v.put("to_amount",toAmount);v.put("to_currency",tc);v.put("business_day",day);v.put("notes",trim(notes));v.put("created_at",now);db.insertOrThrow("currency_exchanges",null,v);cash(db,id,"OUT",fromAmount,fc,fa,now);cash(db,id,"IN",toAmount,tc,ta,now);JSONObject j=new JSONObject().put("exchangeId",id).put("businessDay",day).put("fromAccount",fa).put("fromAmount",fromAmount).put("fromCurrency",fc).put("toAccount",ta).put("toAmount",toAmount).put("toCurrency",tc).put("notes",trim(notes)).put("createdAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SETTING,id,j.toString(),deviceId));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 private static void cash(SQLiteDatabase db,String id,String direction,double amount,String currency,String account,long now){MoneyRules.requireSupported(account,currency);ContentValues v=new ContentValues();v.put("move_id","cash-"+UUID.randomUUID());v.put("source_type","CURRENCY_EXCHANGE");v.put("source_id",id);v.put("direction",direction);v.put("amount",amount);v.put("currency",currency);v.put("payment_method","EXCHANGE");v.put("drawer",account);v.put("created_at",now);db.insertOrThrow("cash_moves",null,v);}private static String req(String v,String l){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}
}
